use vstd::prelude::*;

verus! {
    //
    // A specification‐level function that builds the interleaving of the
    // first i elements of three sequences s1, s2, s3.  It assumes all three
    // sequences have the same length, and i ≤ their common length.
    //
    spec fn interleave_prefix(
        i: nat,
        s1: seq<i32>,
        s2: seq<i32>,
        s3: seq<i32>
    ) -> seq<i32>
        requires
            s1.len() == s2.len(),
            s2.len() == s3.len(),
            i <= s1.len(),
        decreases i,
    {
        if i == 0 {
            seq![]
        } else {
            let prev = interleave_prefix(i - 1, s1, s2, s3);
            prev + seq![ s1[i - 1], s2[i - 1], s3[i - 1] ]
        }
    }

    //
    // Runtime implementation: interleave three Vec<i32> of equal length.
    // We require 3 * n ≤ i32::MAX so that the output length fits in i32.
    // The postcondition says that the resulting Vec's view matches the
    // spec‐level interleave_prefix on the full length.
    //
    fn interleave(
        s1: &Vec<i32>,
        s2: &Vec<i32>,
        s3: &Vec<i32>
    ) -> (res: Vec<i32>)
        requires
            s1.len() == s2.len(),
            s2.len() == s3.len(),
            // ensure 3 * n ≤ i32::MAX
            (s1.len() as nat) * 3 <= i32::MAX as nat,
        ensures
            // length of result is exactly 3 * n
            res.len() == 3 * s1.len(),
            // and its contents are the interleaving
            res.view() == interleave_prefix(
                s1.len() as nat,
                s1.view(),
                s2.view(),
                s3.view()
            ),
    {
        let n = s1.len();
        // pre‐allocate the needed capacity
        let mut res: Vec<i32> = Vec::with_capacity(3 * n);
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                // we've pushed exactly 3*idx elements so far
                res.len() == 3 * idx,
                // and they form the interleaving of the first idx elements
                res.view() == interleave_prefix(
                    idx as nat,
                    s1.view(),
                    s2.view(),
                    s3.view()
                ),
            decreases n - idx,
        {
            // fetch the three elements at position idx
            let x1 = s1[idx];
            let x2 = s2[idx];
            let x3 = s3[idx];
            // push them in order
            res.push(x1);
            res.push(x2);
            res.push(x3);
            // now we've pushed 3 more elements
            assert(res.len() == 3 * (idx + 1));
            // and the view matches the spec definition for idx+1
            assert(res.view() == interleave_prefix(
                (idx + 1) as nat,
                s1.view(),
                s2.view(),
                s3.view()
            ));
            idx = idx + 1;
        }
        res
    }
}

fn main() {
    // (optional) simple runtime smoke‐test
    let a = vec![1, 2, 3];
    let b = vec![10, 20, 30];
    let c = vec![100, 200, 300];
    let r = interleave(&a, &b, &c);
    assert!(r == vec![
        1, 10, 100,
        2, 20, 200,
        3, 30, 300
    ]);
}